 int dp(int x){return Math.round(x*getResources().getDisplayMetrics().density);}int ink(){return dark?0xffdae5f5:0xff1f3048;}TextView text(String label,int size){TextView t=new TextView(getContext());t.setText(label);t.setTextColor(ink());t.setTextSize(size);t.setPadding(dp(4),dp(3),dp(4),dp(3));return t;}LinearLayout row(LinearLayout parent){LinearLayout r=new LinearLayout(getContext());parent.addView(r,new LayoutParams(-1,-2));return r;}
