 void clean(){SectorLeaderModel.need(!dirty,"请先保存或明确取消当前表单");}JSONObject currentBoard()throws JSONException{return SectorLeaderModel.board(config,boardId);}JSONObject selected()throws Exception{JSONArray a=currentBoard().getJSONArray("leaders");for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getString("id").equals(leaderId))return a.getJSONObject(i);throw new IllegalArgumentException("请先选择人工候选");}
 static String provenance(JSONObject q){return q==null||q.length()==0?"尚无报价；未知不是0":q.optString("source")+" · "+q.optString("tradeDate")+" "+q.optString("tradeTime")+" · 检查 "+q.optString("checkedAt")+(q.optBoolean("cached")?" · 旧缓存":"")+(q.optString("error").isEmpty()?"":" · 错误："+q.optString("error"));}
 void working(){for(EditText e:fields().values())e.setEnabled(!busy);roles.setEnabled(!busy);available.setEnabled(!busy);importText.setEnabled(!busy);boards.setEnabled(!busy&&!dirty);}
 void cancel(){generation++;cancelled.set(true);if(job!=null){job.cancel(true);job=null;}javax.net.ssl.HttpsURLConnection c=connection;if(c!=null&&!closer.isShutdown())closer.execute(c::disconnect);busy=false;working();}
 void cancelShown(){cancel();state.setText("已取消未完成任务；已提交记录保留");}
 void run(Work work,Done done){cancel();AtomicBoolean flag=new AtomicBoolean();cancelled=flag;long token=++generation;busy=true;working();job=worker.submit(()->{JSONObject result=null;String failure="";try{result=work.run(flag);}catch(Exception e){failure=error(e);}final JSONObject value=result;final String message=failure;main.post(()->{if(closed||!active||flag.get()||token!=generation)return;busy=false;job=null;if(message.isEmpty())try{done.accept(value);}catch(Exception e){state.setText(error(e));}else state.setText("未完成："+message+"；原人工稿/快照保留");working();});});}
